(function(){angular.module("app.core").factory("permissions",function($rootScope,$filter,localStorageService){var permissionList;return{setPermissions:function(permissions){$rootScope.$broadcast("permissionsChanged")},hasPermission:function(permissions){if(!permissionList){permissionList=localStorageService.get("roleType")
}permissions=permissions;var count=0;angular.forEach(permissions,function(value){if(value===permissionList){count=count+1}});return count!==0}}})}());